solution.solution.c:
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <threads.h>

enum log_level { LOG_DEBUG, LOG_INFO, LOG_WARN, LOG_ERROR };

enum { LINE_SIZE = 140 };

struct logger
{
    mtx_t lock;
    enum log_level min_level;
    int counts[4];
    int capacity;
    int start;
    int used;
    char lines[][LINE_SIZE];
};

static const char *level_name(enum log_level level)
{
    static const char *const names[] = { "DEBUG", "INFO", "WARN", "ERROR" };
    return (unsigned)level < 4 ? names[level] : "?";
}

struct logger *logger_new(enum log_level min_level, int history)
{
    if (history < 1 || history > 64) return NULL;
    struct logger *log = calloc(1, sizeof *log + (size_t)history * LINE_SIZE);
    if (log == NULL) return NULL;
    if (mtx_init(&log->lock, mtx_plain) != thrd_success)
    {
        free(log);
        return NULL;
    }
    log->min_level = min_level;
    log->capacity = history;
    return log;
}

void logger_free(struct logger *log)
{
    if (log == NULL) return;
    mtx_destroy(&log->lock);
    free(log);
}

int logger_write(struct logger *log, enum log_level level, const char *format, ...)
{
    if (level < log->min_level) return 0;
    char message[121];
    va_list args;
    va_start(args, format);
    vsnprintf(message, sizeof message, format, args);
    va_end(args);

    mtx_lock(&log->lock);
    int slot;
    if (log->used < log->capacity)
        slot = (log->start + log->used++) % log->capacity;
    else
    {
        slot = log->start;
        log->start = (log->start + 1) % log->capacity;
    }
    snprintf(log->lines[slot], LINE_SIZE, "[%s] %s", level_name(level), message);
    if ((unsigned)level < 4) log->counts[level]++;
    mtx_unlock(&log->lock);
    return 1;
}

int logger_count(struct logger *log, enum log_level level)
{
    mtx_lock(&log->lock);
    int n = (unsigned)level < 4 ? log->counts[level] : 0;
    mtx_unlock(&log->lock);
    return n;
}

size_t logger_history(struct logger *log, char *out, size_t size)
{
    size_t total = 0;
    if (size > 0) out[0] = '\0';
    mtx_lock(&log->lock);
    for (int i = 0; i < log->used; i++)
    {
        const char *line = log->lines[(log->start + i) % log->capacity];
        size_t n = strlen(line);
        for (size_t k = 0; k <= n; k++)
        {
            char c = k < n ? line[k] : '\n';
            if (size > 0 && total + 1 < size) { out[total] = c; out[total + 1] = '\0'; }
            total++;
        }
    }
    mtx_unlock(&log->lock);
    return total;
}

#define LOG(log, level, ...) logger_write((log), (level), __VA_ARGS__)

unitTests:
TEST("levels and formatting") { struct logger *log = logger_new(LOG_INFO, 4); CHECK(log != NULL); CHECK_EQ(LOG(log, LOG_DEBUG, "not shown: %d", 1), 0); CHECK_EQ(LOG(log, LOG_WARN, "disk %d%% full", 91), 1); CHECK_EQ(LOG(log, LOG_ERROR, "cannot open %s", "save.dat"), 1); char buf[200]; size_t n = logger_history(log, buf, sizeof buf); CHECK_STR(buf, "[WARN] disk 91% full
[ERROR] cannot open save.dat
"); CHECK_EQ((int)n, (int)strlen(buf)); CHECK_EQ(logger_count(log, LOG_WARN), 1); CHECK_EQ(logger_count(log, LOG_DEBUG), 0); logger_free(log); }
TEST("the ring keeps the newest") { struct logger *log = logger_new(LOG_DEBUG, 3); for (int i = 1; i <= 5; i++) LOG(log, LOG_INFO, "line %d", i); char buf[200]; logger_history(log, buf, sizeof buf); CHECK_STR(buf, "[INFO] line 3
[INFO] line 4
[INFO] line 5
"); CHECK_EQ(logger_count(log, LOG_INFO), 5); logger_free(log); }
TEST("history like snprintf") { struct logger *log = logger_new(LOG_DEBUG, 2); LOG(log, LOG_INFO, "abcdef"); char small[8]; size_t n = logger_history(log, small, sizeof small); CHECK_STR(small, "[INFO] "); CHECK_EQ((int)n, 14); CHECK(logger_new(LOG_DEBUG, 0) == NULL); CHECK(logger_new(LOG_DEBUG, 65) == NULL); logger_free(log); }
TEST("long messages are cut") { struct logger *log = logger_new(LOG_DEBUG, 1); char big[300]; memset(big, 'x', 299); big[299] = '\0'; LOG(log, LOG_ERROR, "%s", big); char buf[400]; size_t n = logger_history(log, buf, sizeof buf); CHECK_EQ((int)n, 8 + 120 + 1); logger_free(log); }

